"""Prepared offline; execute only on root's explicit prior-arm QUIET approval."""
import argparse,importlib.util,pathlib,os,json,datetime,hashlib,subprocess
R=pathlib.Path(__file__).resolve().parent

def load(path,name):
 spec=importlib.util.spec_from_file_location(name,path);module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module);return module

def main():
 parser=argparse.ArgumentParser();parser.add_argument('case_label',choices=['capacity_final_1','capacity_final_2']);parser.add_argument('--prior-arm-quiet-approved',action='store_true');a=parser.parse_args()
 if not a.prior_arm_quiet_approved:raise RuntimeError('Root prior-arm QUIET approval required; no database calls were made')
 os.umask(0o077);pg=load(R/'isolated_db.py','pg');my=load(R/'fresh3/isolated_db.py','my');s,i=pg.owned('pg');ms,_=my.owned('mysql');matches=[db for db,v in s['cases'].items() if v['label']==a.case_label];assert len(matches)==1;db=matches[0];out=R/('formal-'+a.case_label+'-instrumentation');out.mkdir(exist_ok=False);path=out/'reset-receipt.json'
 record={'timestamp_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'root_prior_arm_quiet_approved':True,'case_label':a.case_label,'database':db,'pg_container_id':s['id'],'pg_owner':s['owner'],'mysql_container_id':ms['id'],'scope':'Quiet→numeric bounded pgstats preserve→pg_stat_statements_reset only→preflight. No business table/config/log/durability/resource mutation; no workload started.'}
 def save():pg.save(path,record)
 try:
  record['quiet_gate']={'pg_other_clients':pg.sql('pg',"SELECT pid,datname,usename,COALESCE(state,''),COALESCE(wait_event_type,''),COALESCE(wait_event,'') FROM pg_stat_activity WHERE backend_type='client backend' AND pid<>pg_backend_pid();"),'pg_prepared_transactions':pg.sql('pg','SELECT transaction,gid,prepared,owner,database FROM pg_prepared_xacts;'),'mysql_other_clients':my.sql('mysql',"SELECT THREAD_ID,PROCESSLIST_ID,PROCESSLIST_COMMAND,COALESCE(PROCESSLIST_STATE,'') FROM performance_schema.threads WHERE TYPE='FOREGROUND' AND PROCESSLIST_ID<>CONNECTION_ID() AND PROCESSLIST_COMMAND<>'Daemon';"),'mysql_transactions':my.sql('mysql','SELECT trx_id,trx_mysql_thread_id,trx_state FROM information_schema.innodb_trx;'),'mysql_data_locks':my.sql('mysql','SELECT COUNT(*) FROM performance_schema.data_locks;'),'mysql_userlocks':my.sql('mysql',"SELECT OWNER_THREAD_ID,LOCK_STATUS FROM performance_schema.metadata_locks WHERE OBJECT_TYPE='USER LEVEL LOCK';")}
  assert all(not v for k,v in record['quiet_gate'].items() if k!='mysql_data_locks') and record['quiet_gate']['mysql_data_locks']=='0';save()
  cfg=json.loads(pg.sql('pg',"SELECT json_build_object('version',version(),'fsync',current_setting('fsync'),'full_page_writes',current_setting('full_page_writes'),'synchronous_commit',current_setting('synchronous_commit'),'max',current_setting('pg_stat_statements.max'),'track',current_setting('pg_stat_statements.track'),'track_io_timing',current_setting('track_io_timing'));"));assert cfg['fsync']==cfg['full_page_writes']==cfg['synchronous_commit']=='on';maxentries=int(cfg['max']);assert maxentries==1000
  cols=pg.sql('pg',"SELECT column_name FROM information_schema.columns WHERE table_schema='public' AND table_name='pg_stat_statements' AND (column_name IN ('userid','dbid','queryid') OR data_type IN ('smallint','integer','bigint','real','double precision','numeric','boolean','oid')) ORDER BY ordinal_position;").splitlines();assert 'query' not in cols and all(c.replace('_','').isalnum() for c in cols);assert all(c in cols for c in ['dbid','userid','queryid','calls'])
  raw=pg.sql('pg','SELECT row_to_json(t) FROM (SELECT '+','.join(cols)+' FROM pg_stat_statements) t;');rows=[json.loads(line) for line in raw.splitlines() if line];assert len(rows)<=maxentries;info_before=pg.sql('pg','SELECT dealloc,stats_reset FROM pg_stat_statements_info;');before={'timestamp_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'pg_container_id':s['id'],'configuration':cfg,'columns':cols,'entries':len(rows),'rows':rows,'info':info_before,'query_text_or_bindings_included':False};bp=out/'stats-before.json';pg.save(bp,before);record['preserved_stats_file']=str(bp);record['preserved_stats_sha256']=hashlib.sha256(bp.read_bytes()).hexdigest();record['before_entries']=len(rows);record['before_info']=info_before;record['configuration']=cfg;save()
  record['reset_statement']='SELECT pg_stat_statements_reset()';pg.sql('pg',record['reset_statement']+';');record['reset_succeeded']=True;record['reset_observed_utc']=datetime.datetime.now(datetime.timezone.utc).isoformat();record['info_after']=pg.sql('pg','SELECT dealloc,stats_reset FROM pg_stat_statements_info;');record['total_entries_after']=pg.sql('pg','SELECT count(*) FROM pg_stat_statements;');record['arm_database_entries_after']=pg.sql('pg',"SELECT COUNT(*) FROM pg_stat_statements WHERE dbid=(SELECT oid FROM pg_database WHERE datname='"+db+"');");postraw=pg.sql('pg','SELECT row_to_json(t) FROM (SELECT '+','.join(cols)+' FROM pg_stat_statements) t;');postrows=[json.loads(line) for line in postraw.splitlines() if line];assert len(postrows)<=maxentries;postfile=out/'stats-after-reset.json';pg.save(postfile,{'timestamp_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'pg_container_id':s['id'],'configuration':cfg,'columns':cols,'entries':len(postrows),'rows':postrows,'info':record['info_after'],'query_text_or_bindings_included':False});record['preserved_post_stats_file']=str(postfile);record['preserved_post_stats_sha256']=hashlib.sha256(postfile.read_bytes()).hexdigest();record['post_snapshot_entries']=len(postrows);record['semantics']='Only PG statistical counters reset; dealloc/reset time recorded, observer statements can populate immediately. Historical failures and dropped-db statements preserved in before snapshot; no workload success implied.';save()
  record['pg_space']=pg.run(['exec',s['id'],'df','-k','/var/lib/postgresql/data']);record['pg_inodes']=pg.run(['exec',s['id'],'df','-i','/var/lib/postgresql/data']);record['pg_cgroup']=pg.run(['exec',s['id'],'cat','/sys/fs/cgroup/memory.current','/sys/fs/cgroup/memory.max','/sys/fs/cgroup/memory.events']);record['mysql_space']=my.run(['exec',ms['id'],'df','-k','/var/lib/mysql']);record['docker_inventory']=pg.run(['ps','-a','--no-trunc','--format','{{json .}}']).splitlines();record['mysql_pending_engine_status']=my.sql('mysql',"SHOW GLOBAL STATUS WHERE Variable_name IN ('Innodb_data_pending_reads','Innodb_data_pending_writes','Innodb_data_pending_fsyncs','Innodb_os_log_pending_fsyncs','Innodb_os_log_pending_writes','Innodb_log_waits');");record['mysql_log_tail']=subprocess.run(my.D+['logs','--timestamps','--tail','60',ms['id']],capture_output=True,text=True).stderr;record['host_process_snapshot']=subprocess.run(['ps','-axo','pid=,ppid=,%cpu=,%mem=,comm='],capture_output=True,text=True).stdout;record['status']='PRESERVED_RESET_PREFLIGHT_DONE_NO_RUNTIME';save();print(json.dumps({'receipt':str(path),'case_label':a.case_label,'before_entries':len(rows),'before_info':info_before,'after_info':record['info_after'],'after_total_entries':record['total_entries_after'],'arm_database_entries':record['arm_database_entries_after'],'pg_space':record['pg_space']},indent=2))
 except Exception as e:
  record['status']='STOPPED';record['first_error_type']=type(e).__name__;record['first_error']='Subprocess arguments withheld' if isinstance(e,subprocess.SubprocessError) else str(e);save();raise RuntimeError(record['first_error']) from None
if __name__=='__main__':main()
